package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarPathMutaGate1Test {

  @TempDir
  Path tempDir;

  @Test
  void relativizeBehaviors() throws Exception {
    Path tar = tempDir.resolve("a.tar");
    Files.write(tar, new byte[1024]);
    TarFileSystem fs = new TarFileSystem(new TarFileSystemProvider(), tar.toUri(), tar);

    TarPath abc = new TarPath(fs, false, "a/b/c");
    TarPath ad = new TarPath(fs, false, "a/d");
    TarPath a = new TarPath(fs, false, "a");

    // diverging branches
    assertEquals("../../d", abc.relativize(ad).toString());
    assertEquals("../b/c", ad.relativize(abc).toString());

    // identical paths -> empty
    assertEquals("", abc.relativize(new TarPath(fs, false, "a/b/c")).toString());
    assertEquals(0, abc.relativize(abc).getNameCount() == 0 ? 0 : 1);

    // descendant and ancestor
    assertEquals("b/c", a.relativize(abc).toString());
    assertEquals("../..", abc.relativize(a).toString());

    // nothing in common
    assertEquals("../../x/y", new TarPath(fs, false, "p/q").relativize(new TarPath(fs, false, "x/y")).toString());

    // empty receiver
    assertEquals("a/b/c", new TarPath(fs, false, "").relativize(abc).toString());

    // absolute paths yield relative result
    TarPath absAB = new TarPath(fs, true, "a/b");
    TarPath absAC = new TarPath(fs, true, "a/c");
    Path rel = absAB.relativize(absAC);
    assertEquals("../c", rel.toString());
    assertFalse(rel.isAbsolute());

    TarPath root = new TarPath(fs, true, "");
    assertEquals("a/b", root.relativize(absAB).toString());
    assertEquals("../..", absAB.relativize(root).toString());

    // mismatched absolute/relative form
    assertThrows(IllegalArgumentException.class, () -> abc.relativize(absAB));
    assertThrows(IllegalArgumentException.class, () -> absAB.relativize(abc));

    // foreign path implementation
    assertThrows(IllegalArgumentException.class, () -> abc.relativize(Paths.get("a/d")));

    // null
    assertThrows(NullPointerException.class, () -> abc.relativize(null));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

class TarPathMutaGate2Test {

  private static String norm(TarFileSystem fs, boolean absolute, String name) {
    return new TarPath(fs, absolute, name).normalize().toString();
  }

  @Test
  void normalizeHandlesDotAndDotDotSegments() throws Exception {
    Path tar = Files.createTempFile("tarpath-normalize", ".tar");
    try {
      Files.write(tar, new byte[1024]);
      TarFileSystem fs = new TarFileSystem(
          new TarFileSystemProvider(), tar.toUri(), tar);

      // relative paths
      assertEquals("a/c", norm(fs, false, "a/./b/../c"));
      assertEquals("../../a", norm(fs, false, "../../a"));
      assertEquals("..", norm(fs, false, "a/../.."));
      assertEquals("..", norm(fs, false, "../a/.."));
      assertEquals("../b", norm(fs, false, "a/../../b"));
      assertEquals("../..", norm(fs, false, "../.."));
      assertEquals("", norm(fs, false, "a/.."));
      assertEquals("", norm(fs, false, "."));

      // absolute paths: ".." above the root is dropped
      assertEquals("/a", norm(fs, true, "../a"));
      assertEquals("/", norm(fs, true, "a/../.."));
      assertEquals("/b", norm(fs, true, "./a/../b/."));

      // absolute flag is preserved
      assertTrue(new TarPath(fs, true, "a/./b").normalize().isAbsolute());
      assertFalse(new TarPath(fs, false, "a/./b").normalize().isAbsolute());

      // result belongs to the same file system
      assertEquals(fs, new TarPath(fs, false, "a/.").normalize().getFileSystem());
    } finally {
      Files.deleteIfExists(tar);
    }
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

class TarPathMutaGate3Test {

  @Test
  void constructorNormalizesEntryName() throws Exception {
    Path tmp = Files.createTempFile("tarpath-test", ".tar");
    try {
      Files.write(tmp, new byte[1024]);
      TarFileSystem fs = new TarFileSystem(new TarFileSystemProvider(), URI.create("tar:" + tmp + "!"), tmp);

      TarPath messy = new TarPath(fs, false, "//a\\b//c///");
      assertEquals(3, messy.getNameCount());
      assertEquals("a/b/c", messy.entryName());
      assertEquals("a/b/c", messy.toString());
      assertEquals("a", messy.getName(0).toString());
      assertEquals("b", messy.getName(1).toString());
      assertEquals("c", messy.getName(2).toString());

      TarPath absRoot = new TarPath(fs, true, "");
      assertEquals(0, absRoot.getNameCount());
      assertEquals("/", absRoot.toString());
      assertEquals("", absRoot.entryName());

      TarPath nullName = new TarPath(fs, false, null);
      assertEquals(0, nullName.getNameCount());
      assertEquals("", nullName.toString());

      TarPath onlySlashes = new TarPath(fs, true, "///");
      assertEquals(0, onlySlashes.getNameCount());
      assertEquals("/", onlySlashes.toString());

      TarPath onlyBackslashes = new TarPath(fs, false, "\\\\");
      assertEquals(0, onlyBackslashes.getNameCount());

      TarPath absolute = new TarPath(fs, true, "/x/y/");
      assertEquals("/x/y", absolute.toString());
      assertEquals(2, absolute.getNameCount());

      assertEquals(new TarPath(fs, false, "a/b/c"), messy);
      assertEquals(new TarPath(fs, false, "a/b/c").hashCode(), messy.hashCode());
      assertNotEquals(new TarPath(fs, true, "a/b/c"), messy);

      NullPointerException npe =
          assertThrows(NullPointerException.class, () -> new TarPath(null, false, "a"));
      assertEquals("fileSystem", npe.getMessage());
    } finally {
      Files.deleteIfExists(tmp);
    }
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarPathMutaGate4Test {

  @Test
  void startsWithBehaviors(@TempDir Path dir) throws Exception {
    Path tar = dir.resolve("test.tar");
    Files.write(tar, new byte[1024]);
    TarFileSystemProvider provider = new TarFileSystemProvider();
    TarFileSystem fs = new TarFileSystem(provider, URI.create("tar:" + tar.toAbsolutePath() + "!"), tar);

    TarPath abs = new TarPath(fs, true, "a/b/c");
    TarPath rel = new TarPath(fs, false, "a/b/c");

    // proper prefixes
    assertTrue(abs.startsWith(new TarPath(fs, true, "a")));
    assertTrue(abs.startsWith(new TarPath(fs, true, "a/b")));
    assertTrue(rel.startsWith(new TarPath(fs, false, "a/b")));

    // equal path
    assertTrue(abs.startsWith(new TarPath(fs, true, "a/b/c")));
    assertTrue(rel.startsWith(new TarPath(fs, false, "a/b/c")));

    // root / empty prefixes
    assertTrue(abs.startsWith(new TarPath(fs, true, "")));
    assertTrue(rel.startsWith(new TarPath(fs, false, "")));
    assertTrue(new TarPath(fs, true, "").startsWith(new TarPath(fs, true, "")));

    // absolute/relative mismatch
    assertFalse(abs.startsWith(new TarPath(fs, false, "a")));
    assertFalse(rel.startsWith(new TarPath(fs, true, "a")));
    assertFalse(abs.startsWith(new TarPath(fs, false, "")));

    // other longer than this
    assertFalse(new TarPath(fs, true, "a/b").startsWith(abs));
    assertFalse(new TarPath(fs, true, "").startsWith(new TarPath(fs, true, "a")));

    // differing segments
    assertFalse(abs.startsWith(new TarPath(fs, true, "b")));
    assertFalse(abs.startsWith(new TarPath(fs, true, "a/x")));
    assertFalse(abs.startsWith(new TarPath(fs, true, "a/b/x")));

    // segment-wise, not string prefix
    assertFalse(new TarPath(fs, true, "ab/c").startsWith(new TarPath(fs, true, "a")));

    // non-TarPath argument
    assertFalse(abs.startsWith(Path.of("a")));
    assertFalse(rel.startsWith(Path.of("a")));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarPathMutaGate5Test {

  @TempDir
  Path tempDir;

  private TarFileSystem newFs(String name) throws IOException {
    Path tar = tempDir.resolve(name);
    Files.write(tar, new byte[1024]);
    return new TarFileSystem(new TarFileSystemProvider(), tar.toUri(), tar);
  }

  @Test
  void resolveBehaviors() throws IOException {
    TarFileSystem fs = newFs("one.tar");
    TarFileSystem other = newFs("two.tar");

    // absolute base + relative other keeps absolute form and joins segments
    TarPath absBase = new TarPath(fs, true, "a/b");
    Path r1 = absBase.resolve(new TarPath(fs, false, "c/d"));
    assertEquals(new TarPath(fs, true, "a/b/c/d"), r1);
    assertTrue(r1.isAbsolute());
    assertEquals("/a/b/c/d", r1.toString());

    // relative base stays relative
    TarPath relBase = new TarPath(fs, false, "a");
    Path r2 = relBase.resolve(new TarPath(fs, false, "b"));
    assertFalse(r2.isAbsolute());
    assertEquals("a/b", r2.toString());

    // root base resolves to just the other entry, no leading duplicate separators
    TarPath root = new TarPath(fs, true, "");
    Path r3 = root.resolve(new TarPath(fs, false, "x"));
    assertEquals("/x", r3.toString());

    // empty other yields an equal path to base
    assertEquals(absBase, absBase.resolve(new TarPath(fs, false, "")));

    // empty base and empty other
    assertEquals(new TarPath(fs, false, ""), new TarPath(fs, false, "").resolve(new TarPath(fs, false, "")));

    // absolute other is returned as-is, even from a different file system
    TarPath absOther = new TarPath(fs, true, "z");
    assertSame(absOther, relBase.resolve(absOther));
    TarPath foreignAbs = new TarPath(other, true, "q");
    assertSame(foreignAbs, absBase.resolve(foreignAbs));

    // string overload
    assertEquals(new TarPath(fs, true, "a/b/e/f"), absBase.resolve("e/f"));

    // relative path from a different file system is rejected
    assertThrows(IllegalArgumentException.class,
        () -> absBase.resolve(new TarPath(other, false, "c")));

    // relative non-TarPath is rejected
    assertThrows(IllegalArgumentException.class, () -> absBase.resolve(Path.of("rel")));

    // null is rejected
    assertThrows(NullPointerException.class, () -> absBase.resolve((Path) null));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarPathMutaGate6Test {

  @Test
  void iteratorYieldsRelativeNameElementsInOrderAndThenEnds(@TempDir Path dir) throws Exception {
    Path tar = dir.resolve("archive.tar");
    Files.write(tar, new byte[1024]);
    TarFileSystemProvider provider = new TarFileSystemProvider();
    TarFileSystem fs = new TarFileSystem(provider, URI.create("tar:" + tar.toAbsolutePath() + "!"), tar);

    TarPath path = new TarPath(fs, true, "a/b/c");
    Iterator<Path> it = path.iterator();

    // hasNext is idempotent and does not advance
    assertTrue(it.hasNext());
    assertTrue(it.hasNext());

    List<Path> seen = new ArrayList<>();
    while (it.hasNext()) {
      seen.add(it.next());
    }

    assertEquals(3, seen.size());
    assertEquals(new TarPath(fs, false, "a"), seen.get(0));
    assertEquals(new TarPath(fs, false, "b"), seen.get(1));
    assertEquals(new TarPath(fs, false, "c"), seen.get(2));
    for (Path p : seen) {
      assertFalse(p.isAbsolute());
      assertEquals(1, p.getNameCount());
    }

    assertFalse(it.hasNext());
    assertThrows(IndexOutOfBoundsException.class, it::next);

    // each call to iterator() starts fresh
    assertTrue(path.iterator().hasNext());
    assertEquals(new TarPath(fs, false, "a"), path.iterator().next());

    // root and empty relative paths have no elements
    assertFalse(new TarPath(fs, true, "").iterator().hasNext());
    assertFalse(new TarPath(fs, false, "").iterator().hasNext());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarPathMutaGate7Test {

  @TempDir
  Path tempDir;

  @Test
  void endsWithComparesTrailingSegmentsOnly() throws Exception {
    Path tar = tempDir.resolve("test.tar");
    Files.write(tar, new byte[1024]);
    TarFileSystem fs = new TarFileSystem(new TarFileSystemProvider(), URI.create("tar:" + tar.toAbsolutePath() + "!"), tar);

    TarPath abs = new TarPath(fs, true, "a/b/c");
    TarPath rel = new TarPath(fs, false, "a/b/c");

    // suffix of segments matches
    assertTrue(abs.endsWith(new TarPath(fs, false, "c")));
    assertTrue(abs.endsWith(new TarPath(fs, false, "b/c")));
    assertTrue(abs.endsWith(new TarPath(fs, false, "a/b/c")));

    // absoluteness of other is not considered by endsWith
    assertTrue(abs.endsWith(new TarPath(fs, true, "a/b/c")));
    assertTrue(rel.endsWith(new TarPath(fs, true, "a/b/c")));
    assertTrue(rel.endsWith(new TarPath(fs, true, "b/c")));

    // empty other has no segments, so it matches
    assertTrue(abs.endsWith(new TarPath(fs, false, "")));
    assertTrue(rel.endsWith(new TarPath(fs, true, "")));

    // string overload
    assertTrue(abs.endsWith("b/c"));
    assertFalse(abs.endsWith("a/b"));

    // mismatches
    assertFalse(abs.endsWith(new TarPath(fs, false, "b")));
    assertFalse(abs.endsWith(new TarPath(fs, false, "a/c")));
    assertFalse(abs.endsWith(new TarPath(fs, false, "x/b/c")));

    // partial segment name does not match
    assertFalse(new TarPath(fs, false, "ab").endsWith(new TarPath(fs, false, "b")));

    // other longer than this
    assertFalse(new TarPath(fs, false, "b/c").endsWith(new TarPath(fs, false, "a/b/c")));
    assertFalse(new TarPath(fs, true, "").endsWith(new TarPath(fs, false, "a")));

    // non-TarPath argument
    assertFalse(abs.endsWith(Path.of("c")));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarPathMutaGate8Test {

  @Test
  void equalsDistinguishesFileSystemAbsoluteAndSegments(@TempDir Path dir) throws Exception {
    Path tar1 = dir.resolve("one.tar");
    Path tar2 = dir.resolve("two.tar");
    Files.write(tar1, new byte[1024]);
    Files.write(tar2, new byte[1024]);

    TarFileSystemProvider provider = new TarFileSystemProvider();
    TarFileSystem fs1 = new TarFileSystem(provider, URI.create("tar:" + tar1.toAbsolutePath() + "!"), tar1);
    TarFileSystem fs2 = new TarFileSystem(provider, URI.create("tar:" + tar2.toAbsolutePath() + "!"), tar2);

    TarPath a = new TarPath(fs1, true, "a/b");

    // reflexive and equal to a separately constructed identical path
    assertTrue(a.equals(a));
    TarPath same = new TarPath(fs1, true, "a/b");
    assertTrue(a.equals(same));
    assertTrue(same.equals(a));
    assertEquals(a.hashCode(), same.hashCode());

    // normalization of separators in the constructor
    assertTrue(a.equals(new TarPath(fs1, true, "/a/b/")));
    assertTrue(a.equals(new TarPath(fs1, true, "a\\b")));
    assertTrue(a.equals(new TarPath(fs1, true, "a//b")));

    // different absolute flag
    assertFalse(a.equals(new TarPath(fs1, false, "a/b")));
    assertFalse(new TarPath(fs1, false, "a/b").equals(a));

    // different file system, same content
    assertFalse(a.equals(new TarPath(fs2, true, "a/b")));

    // different segments
    assertFalse(a.equals(new TarPath(fs1, true, "a/c")));
    assertFalse(a.equals(new TarPath(fs1, true, "c/b")));
    assertFalse(a.equals(new TarPath(fs1, true, "a")));
    assertFalse(a.equals(new TarPath(fs1, true, "a/b/c")));

    // roots
    assertTrue(new TarPath(fs1, true, "").equals(new TarPath(fs1, true, "/")));
    assertFalse(new TarPath(fs1, true, "").equals(new TarPath(fs1, false, "")));

    // null and foreign types
    assertFalse(a.equals(null));
    assertFalse(a.equals("/a/b"));
    assertFalse(a.equals(new Object()));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

class TarPathMutaGate9Test {

  @Test
  void toUriBuildsTarUriFromArchiveAndEntryName() throws Exception {
    Path tar = Files.createTempFile("archive", ".tar");
    try {
      Files.write(tar, new byte[1024]);
      TarFileSystemProvider provider = new TarFileSystemProvider();
      TarFileSystem fs = new TarFileSystem(provider, URI.create("tar:" + tar.toAbsolutePath() + "!"), tar);
      try {
        String archive = fs.tarFile().toAbsolutePath().toString();

        // Root: no entry, URI ends with "!"
        assertEquals(URI.create("tar:" + archive + "!"), new TarPath(fs, true, "").toUri());
        assertEquals(URI.create("tar:" + archive + "!"), new TarPath(fs, false, "").toUri());

        // Entry path, absolute and relative produce the same URI
        URI expected = URI.create("tar:" + archive + "!dir/file.txt");
        assertEquals(expected, new TarPath(fs, true, "/dir/file.txt").toUri());
        assertEquals(expected, new TarPath(fs, false, "dir/file.txt").toUri());

        // Trailing slashes and backslashes are normalized in the entry name
        assertEquals(expected, new TarPath(fs, true, "dir\\file.txt/").toUri());

        // Scheme is "tar"
        assertEquals("tar", expected.getScheme());
      } finally {
        fs.close();
      }
    } finally {
      Files.deleteIfExists(tar);
    }
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.ClosedFileSystemException;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarPathMutaGate10Test {

  @TempDir
  Path tempDir;

  private static byte[] buildTar(String name, String content) throws IOException {
    byte[] data = content.getBytes(StandardCharsets.US_ASCII);
    byte[] header = new byte[512];
    put(header, 0, name);
    put(header, 100, "0000644\0");
    put(header, 108, "0000000\0");
    put(header, 116, "0000000\0");
    put(header, 124, String.format("%011o", data.length) + "\0");
    put(header, 136, String.format("%011o", 0) + "\0");
    for (int i = 148; i < 156; i++) {
      header[i] = ' ';
    }
    header[156] = '0';
    put(header, 257, "ustar\0");
    put(header, 263, "00");
    long sum = 0;
    for (byte b : header) {
      sum += (b & 0xff);
    }
    put(header, 148, String.format("%06o", sum) + "\0 ");

    ByteArrayOutputStream out = new ByteArrayOutputStream();
    out.write(header);
    out.write(data);
    int pad = (512 - (data.length % 512)) % 512;
    out.write(new byte[pad]);
    out.write(new byte[1024]);
    return out.toByteArray();
  }

  private static void put(byte[] buf, int offset, String s) {
    byte[] b = s.getBytes(StandardCharsets.US_ASCII);
    System.arraycopy(b, 0, buf, offset, b.length);
  }

  @Test
  void toRealPathNormalizesChecksExistenceAndFailsWhenClosed() throws IOException {
    Path tar = tempDir.resolve("test.tar");
    Files.write(tar, buildTar("hello.txt", "hello"));

    FileSystem fs = new TarFileSystemProvider().newFileSystem(tar, Map.of());
    Path existing;
    try {
      existing = fs.getPath("dir/../hello.txt");
      Path real = existing.toRealPath();
      assertTrue(real.isAbsolute());
      assertEquals("/hello.txt", real.toString());

      Path missing = fs.getPath("a/./b/../missing.txt");
      NoSuchFileException ex = assertThrows(NoSuchFileException.class, missing::toRealPath);
      assertEquals("/a/missing.txt", ex.getFile());
    } finally {
      fs.close();
    }

    assertThrows(ClosedFileSystemException.class, existing::toRealPath);
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.File;
import java.net.URI;
import java.nio.file.ClosedFileSystemException;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarPathMutaGate11Test {

  @TempDir
  Path tempDir;

  @Test
  void toFileBehavior() throws Exception {
    Path tar = tempDir.resolve("archive.tar");
    Files.write(tar, new byte[1024]);

    TarFileSystemProvider provider = new TarFileSystemProvider();
    TarFileSystem fs = new TarFileSystem(provider, URI.create("tar:" + tar.toAbsolutePath() + "!"), tar);

    File expected = fs.tarFile().toFile();

    // Root (absolute and empty relative) maps to the tar file itself
    assertEquals(expected, new TarPath(fs, true, "").toFile());
    assertEquals(expected, new TarPath(fs, false, "").toFile());
    assertEquals(expected, new TarPath(fs, false, "/").toFile());

    // Any actual entry cannot be mapped to a host file
    assertThrows(UnsupportedOperationException.class, () -> new TarPath(fs, true, "a/b.txt").toFile());
    assertThrows(UnsupportedOperationException.class, () -> new TarPath(fs, false, "a").toFile());

    // After closing, toFile fails even for the root
    fs.close();
    assertThrows(ClosedFileSystemException.class, () -> new TarPath(fs, true, "").toFile());
    assertThrows(ClosedFileSystemException.class, () -> new TarPath(fs, false, "a").toFile());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarPathMutaGate12Test {

  @TempDir
  Path tempDir;

  @Test
  void getParentBehavior() throws Exception {
    Path tar = tempDir.resolve("test.tar");
    Files.write(tar, new byte[1024]);
    TarFileSystem fs = new TarFileSystem(
        new TarFileSystemProvider(), URI.create("tar:" + tar.toAbsolutePath() + "!"), tar);

    // absolute multi-segment: parent drops last segment and stays absolute
    Path abs = new TarPath(fs, true, "a/b/c");
    Path absParent = abs.getParent();
    assertNotNull(absParent);
    assertTrue(absParent.isAbsolute());
    assertEquals(new TarPath(fs, true, "a/b"), absParent);
    assertEquals("/a/b", absParent.toString());
    assertEquals(2, absParent.getNameCount());

    // relative multi-segment: parent stays relative
    Path rel = new TarPath(fs, false, "a/b/c");
    Path relParent = rel.getParent();
    assertNotNull(relParent);
    assertFalse(relParent.isAbsolute());
    assertEquals(new TarPath(fs, false, "a/b"), relParent);
    assertEquals("a/b", relParent.toString());

    // two segments
    assertEquals(new TarPath(fs, false, "a"), new TarPath(fs, false, "a/b").getParent());
    assertEquals("/a", new TarPath(fs, true, "a/b").getParent().toString());

    // single segment: absolute -> root, relative -> null
    Path rootParent = new TarPath(fs, true, "a").getParent();
    assertNotNull(rootParent);
    assertTrue(rootParent.isAbsolute());
    assertEquals(0, rootParent.getNameCount());
    assertEquals("/", rootParent.toString());
    assertNull(new TarPath(fs, false, "a").getParent());

    // no segments: null for both root and empty relative path
    assertNull(new TarPath(fs, true, "").getParent());
    assertNull(new TarPath(fs, false, "").getParent());

    // repeated getParent walks up to root, then null
    Path p = new TarPath(fs, true, "x/y/z");
    assertEquals("/x/y", p.getParent().toString());
    assertEquals("/x", p.getParent().getParent().toString());
    assertEquals("/", p.getParent().getParent().getParent().toString());
    assertNull(p.getParent().getParent().getParent().getParent());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarPathMutaGate13Test {

  @TempDir
  Path tempDir;

  @Test
  void resolveSiblingCoversParentAndNoParentCases() throws Exception {
    Path tar = tempDir.resolve("test.tar");
    Files.write(tar, new byte[1024]);
    TarFileSystemProvider provider = new TarFileSystemProvider();
    TarFileSystem fs = new TarFileSystem(provider, URI.create("tar:" + tar.toAbsolutePath() + "!"), tar);

    // Relative path with a parent: sibling replaces last segment
    TarPath relative = new TarPath(fs, false, "a/b");
    assertEquals(new TarPath(fs, false, "a/c"), relative.resolveSibling(new TarPath(fs, false, "c")));
    assertEquals(new TarPath(fs, false, "a/x/y"), relative.resolveSibling(new TarPath(fs, false, "x/y")));

    // Absolute path with a parent
    TarPath absolute = new TarPath(fs, true, "a/b/c");
    assertEquals(new TarPath(fs, true, "a/b/d"), absolute.resolveSibling(new TarPath(fs, false, "d")));

    // Absolute single segment: parent is root
    TarPath absSingle = new TarPath(fs, true, "a");
    assertEquals(new TarPath(fs, true, "c"), absSingle.resolveSibling(new TarPath(fs, false, "c")));

    // Relative single segment: no parent, so resolves other against itself
    TarPath relSingle = new TarPath(fs, false, "a");
    assertEquals("a/c", relSingle.resolveSibling(new TarPath(fs, false, "c")).toString());

    // Root: no parent
    TarPath root = new TarPath(fs, true, "");
    assertEquals(new TarPath(fs, true, "c"), root.resolveSibling(new TarPath(fs, false, "c")));

    // Absolute other is returned as is
    TarPath otherAbs = new TarPath(fs, true, "z");
    assertSame(otherAbs, relative.resolveSibling(otherAbs));
    assertSame(otherAbs, relSingle.resolveSibling(otherAbs));
  }
}

