import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.file.FileSystems;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardWatchEventKinds;
import java.nio.file.WatchEvent;
import java.nio.file.WatchService;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarPathMutaGate20Test {

  @Test
  void registerAlwaysThrowsUnsupportedOperationWithMessage(@TempDir Path dir) throws Exception {
    Path tar = dir.resolve("empty.tar");
    Files.write(tar, new byte[1024]);

    TarFileSystemProvider provider = new TarFileSystemProvider();
    TarFileSystem fs = new TarFileSystem(provider, java.net.URI.create("tar:" + tar.toAbsolutePath() + "!"), tar);
    TarPath path = new TarPath(fs, true, "some/entry.txt");

    WatchEvent.Kind<?>[] events = {StandardWatchEventKinds.ENTRY_CREATE};

    try (WatchService watcher = FileSystems.getDefault().newWatchService()) {
      UnsupportedOperationException ex = assertThrows(UnsupportedOperationException.class,
          () -> path.register(watcher, events));
      assertEquals("Watch service is not implemented for tar entries", ex.getMessage());

      UnsupportedOperationException ex2 = assertThrows(UnsupportedOperationException.class,
          () -> path.register(watcher, new WatchEvent.Kind<?>[0], new WatchEvent.Modifier[0]));
      assertEquals("Watch service is not implemented for tar entries", ex2.getMessage());
    }

    // Even with null arguments, the same exception is thrown (no null checks beforehand)
    UnsupportedOperationException ex3 = assertThrows(UnsupportedOperationException.class,
        () -> path.register(null, null));
    assertEquals("Watch service is not implemented for tar entries", ex3.getMessage());
  }
}

