    TarPath p = new TarPath(fs, true, "/one/two/three");
    assertEquals("one/two", ((TarPath) p.getParent()).entryName());
    assertEquals("three", ((TarPath) p.getFileName()).entryName());
    assertEquals("two/three", ((TarPath) p.subpath(1, 3)).entryName());
